// ---- END map-world-data ----
// ---- 地図のデータを読む（作るときに投影を済ませた整数の座標。1 単位 ≈ 1 km、y は下向き）
var ALPH = MAP.alph;
function decode(s){
  var out = [], v = 0, sh = 1;
  for (var i = 0; i < s.length; i++){
    var d = ALPH.indexOf(s[i]);
    if (d >= 32){ v += (d - 32) * sh; sh *= 32; }
    else { v += d * sh; out.push(v % 2 ? -(v + 1) / 2 : v / 2); v = 0; sh = 1; }
  }
  return out;
}
var ARCS = (function(){
  var n = decode(MAP.arcs), arcs = [], i = 0;
  while (i < n.length){
    var c = n[i++], a = [], x = 0, y = 0;
    for (var j = 0; j < c; j++){ x += n[i++]; y += n[i++]; a.push([x, y]); }
    arcs.push(a);
  }
  return arcs;
})();
function ring(idx){
  var r = [];
  idx.forEach(function(i){
    var a = i < 0 ? ARCS[~i].slice().reverse() : ARCS[i];
    for (var j = r.length ? 1 : 0; j < a.length; j++) r.push(a[j]);
  });
  return r;
}
// 形：{id: [[外の環, 穴…]…]}（形の残らない小さな国・地域は無い）
// 海外の部分（フランス領ギアナなど）は、その地理の州の部分として別に持つ（f[2] が州。docs: README の注意）
var SHAPE = {}, PIECE = {};
MAP.feats.forEach(function(f){
  var polys = f[1].map(function(p){ return p.map(ring); });
  SHAPE[f[0]] = (SHAPE[f[0]] || []).concat(polys);
  (PIECE[f[0]] = PIECE[f[0]] || []).push({g: f[2] || "", polys: polys});
});
var NAME = {}, GROUP_OF = {}, CODE_BY = {}, IDS = [];
MAP.list.forEach(function(c){
  IDS.push(c[0]); NAME[c[0]] = c[2]; GROUP_OF[c[0]] = c[3];
  CODE_BY[c[0]] = c[0];
  if (c[1] && !CODE_BY[c[1]]) CODE_BY[c[1]] = c[0];
  if (c[2] && !CODE_BY[c[2]]) CODE_BY[c[2]] = c[0];
});
// 州の構成：国の符号（国全体）か「符号@州」（その州にある海外の部分だけ。例 FRA@south-america）
var GROUP = {};
MAP.groups.forEach(function(g){
  var codes = [];
  IDS.forEach(function(c){
    var gs = (PIECE[c] || [{g: ""}]).map(function(q){ return q.g || GROUP_OF[c]; });
    if (gs.indexOf(g[0]) < 0) return;
    codes.push(gs.every(function(x){ return x === g[0]; }) ? c : c + "@" + g[0]);
  });
  var o = {id: g[0], name: g[1], anchor: g[2], codes: codes};
  GROUP[g[0]] = GROUP[g[1]] = GROUP[g[1].replace(/州$/, "")] = o;
});
var idOf = function(k){ return k.split("@")[0]; };
